import{_ as a,o as r,c as o,a2 as i}from"./chunks/framework.CgxQ0r6v.js";const m=JSON.parse('{"title":"Manual de Estudio Profundo: Evaluación 4","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Redes/documentacion/II-V/Lectura_Catedra_Evaluacion_4.md","filePath":"materias/Redes/documentacion/II-V/Lectura_Catedra_Evaluacion_4.md"}'),t={name:"materias/Redes/documentacion/II-V/Lectura_Catedra_Evaluacion_4.md"};function n(s,e,l,d,c,u){return r(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="manual-de-estudio-profundo-evaluacion-4" tabindex="-1">Manual de Estudio Profundo: Evaluación 4 <a class="header-anchor" href="#manual-de-estudio-profundo-evaluacion-4" aria-label="Permalink to &quot;Manual de Estudio Profundo: Evaluación 4&quot;">​</a></h1><h2 id="materia-redes-trayecto-ii" tabindex="-1">Materia: Redes (Trayecto II) <a class="header-anchor" href="#materia-redes-trayecto-ii" aria-label="Permalink to &quot;Materia: Redes (Trayecto II)&quot;">​</a></h2><h3 id="eje-tematico-seguridad-perimetral-y-redes-privadas-vpns" tabindex="-1">Eje Temático: Seguridad Perimetral y Redes Privadas (VPNs) <a class="header-anchor" href="#eje-tematico-seguridad-perimetral-y-redes-privadas-vpns" aria-label="Permalink to &quot;Eje Temático: Seguridad Perimetral y Redes Privadas (VPNs)&quot;">​</a></h3><hr><h2 id="🧭-introduccion-defendiendo-el-castillo" tabindex="-1">🧭 Introducción: Defendiendo el Castillo <a class="header-anchor" href="#🧭-introduccion-defendiendo-el-castillo" aria-label="Permalink to &quot;🧭 Introducción: Defendiendo el Castillo&quot;">​</a></h2><p>Un servidor conectado a internet sin protección recibe, en promedio, un intento de ataque automatizado por fuerza bruta desde Rusia, China o Estados Unidos cada <strong>30 segundos</strong>. Internet es una zona de guerra hostil plagada de <em>bots</em> diseñados para secuestrar equipos e inyectar <em>Ransomware</em> (secuestro de datos a cambio de criptomonedas).</p><p>La culminación de tus estudios de redes en este trimestre se enfoca en la <strong>Seguridad Perimetral</strong>. Si la red de tu empresa es un castillo, hoy aprenderás a construir la muralla, a configurar a los guardias en el puente levadizo y a crear túneles subterráneos secretos para los aliados.</p><hr><h2 id="🏛️-capitulo-i-el-firewall-cortafuegos" tabindex="-1">🏛️ CAPÍTULO I: El Firewall (Cortafuegos) <a class="header-anchor" href="#🏛️-capitulo-i-el-firewall-cortafuegos" aria-label="Permalink to &quot;🏛️ CAPÍTULO I: El Firewall (Cortafuegos)&quot;">​</a></h2><p>Un Firewall es el sistema de seguridad primario de la red. Puede ser un equipo de hardware físico muy costoso (como los de Palo Alto o Cisco ASA) que se pone justo en la frontera entre la red de tu empresa y el Router de internet, o puede ser un software ejecutándose dentro de tu servidor Linux.</p><p>El Firewall funciona inspeccionando cada &quot;paquete&quot; de red entrante y saliente y comparándolo contra una estricta <strong>Lista de Control de Acceso (ACL - Access Control List)</strong>.</p><h3 id="_1-1-filtrado-por-reglas-el-guardia-del-puente" tabindex="-1">1.1 Filtrado por Reglas (El Guardia del Puente) <a class="header-anchor" href="#_1-1-filtrado-por-reglas-el-guardia-del-puente" aria-label="Permalink to &quot;1.1 Filtrado por Reglas (El Guardia del Puente)&quot;">​</a></h3><p>La filosofía moderna de seguridad es de <strong>&quot;Denegación Implícita&quot; (Default Deny)</strong>. Consiste en una regla general al final de la lista: <em>&quot;Si no estás en mi lista de invitados VIP, estás bloqueado&quot;</em>. Luego, configuras excepciones:</p><ul><li><strong>Regla 1:</strong> Permitir entrada de paquetes por el Puerto 80 y 443 (Tráfico Web HTTP/HTTPS para que los clientes vean tu página).</li><li><strong>Regla 2:</strong> Permitir entrada por el Puerto 22 (SSH) SOLO SI la petición proviene de la dirección IP de la casa del Administrador de Sistemas. Todos los demás intentos de conexión SSH desde el planeta serán descartados (Droppeados) silenciosamente.</li></ul><h3 id="_1-2-iptables-el-motor-linux" tabindex="-1">1.2 Iptables (El Motor Linux) <a class="header-anchor" href="#_1-2-iptables-el-motor-linux" aria-label="Permalink to &quot;1.2 Iptables (El Motor Linux)&quot;">​</a></h3><p>En servidores Linux, el cortafuegos interno más famoso se llama <code>iptables</code> (y su sucesor moderno <code>nftables</code>). Trabaja directamente en el núcleo (Kernel) del sistema operativo, interceptando la red a velocidades extremas.</p><hr><h2 id="🧩-capitulo-ii-tuneles-secretos-vpn-virtual-private-network" tabindex="-1">🧩 CAPÍTULO II: Túneles Secretos (VPN - Virtual Private Network) <a class="header-anchor" href="#🧩-capitulo-ii-tuneles-secretos-vpn-virtual-private-network" aria-label="Permalink to &quot;🧩 CAPÍTULO II: Túneles Secretos (VPN - Virtual Private Network)&quot;">​</a></h2><p>Supongamos que el Gerente General está de viaje en Japón, en el Wi-Fi gratuito e inseguro de un Starbucks, y necesita entrar a la base de datos de facturación de la empresa en Caracas para aprobar un pago. La base de datos es súper secreta y el Firewall de la empresa tiene estrictamente bloqueado el acceso desde el exterior.</p><p>¿Cómo hacemos que el Gerente entre como si estuviera físicamente sentado en la oficina en Caracas, sin abrirle un hueco de seguridad al Firewall de la empresa? <strong>Construyendo una VPN.</strong></p><h3 id="_2-1-el-funcionamiento-de-la-vpn" tabindex="-1">2.1 El Funcionamiento de la VPN <a class="header-anchor" href="#_2-1-el-funcionamiento-de-la-vpn" aria-label="Permalink to &quot;2.1 El Funcionamiento de la VPN&quot;">​</a></h3><ol><li>El gerente abre un programa cliente VPN en su laptop en Japón.</li><li>Este programa se conecta a un servidor VPN (ej. OpenVPN o WireGuard) instalado dentro del edificio de la empresa en Caracas.</li><li>Se crea un <strong>Túnel Cifrado</strong> a través de internet (IPsec). Todo lo que el gerente envíe, se empaqueta en una &quot;cápsula&quot; blindada con criptografía extrema. Nadie en el cibercafé de Japón ni en las operadoras de internet internacionales puede ver qué datos van allí.</li><li>Cuando la cápsula llega al servidor de Caracas, se abre. Para los servidores locales (y el Firewall), parece que la petición vino desde el servidor VPN que está físicamente al lado de ellos en la red LAN.</li><li>El gerente accede a la base de datos de forma 100% invisible y segura.</li></ol><hr><h2 id="🏗️-capitulo-iii-control-de-acceso-local-tcp-wrappers-y-pam" tabindex="-1">🏗️ CAPÍTULO III: Control de Acceso Local (TCP Wrappers y PAM) <a class="header-anchor" href="#🏗️-capitulo-iii-control-de-acceso-local-tcp-wrappers-y-pam" aria-label="Permalink to &quot;🏗️ CAPÍTULO III: Control de Acceso Local (TCP Wrappers y PAM)&quot;">​</a></h2><p>Además de proteger la frontera exterior (Firewall), debemos asegurar las puertas internas del servidor (Defensa en Profundidad).</p><ul><li><strong>TCP Wrappers (<code>/etc/hosts.allow</code> y <code>/etc/hosts.deny</code>):</strong> Es una herramienta clásica de Linux. Antes de que un servicio interno (como FTP o SSH) responda, el &quot;Wrapper&quot; (Envoltorio) revisa si la IP de origen está en el archivo de los permitidos. Si está en la lista de los denegados, le corta el teléfono en la cara inmediatamente.</li><li><strong>PAM (Pluggable Authentication Modules):</strong> Es el corazón del login en Linux. PAM permite crear reglas ultra complejas de autenticación. Por ejemplo: configurar PAM para obligar a que todos los administradores necesiten usar su celular y colocar un código de Google Authenticator (MFA - Múltiple Factor de Autenticación) después de poner su contraseña.</li></ul><hr><h2 id="💻-resumen-del-trimestre-ii" tabindex="-1">💻 Resumen del Trimestre II <a class="header-anchor" href="#💻-resumen-del-trimestre-ii" aria-label="Permalink to &quot;💻 Resumen del Trimestre II&quot;">​</a></h2><p>Has dado el salto de técnico instalador de cables a <strong>Ingeniero Administrador de Infraestructuras</strong>. Ahora dominas:</p><ol><li>El diseño topológico profesional y los estándares Wi-Fi (IEEE 802.11).</li><li>La arquitectura lógica del internet, el enrutamiento y la partición de redes (Subnetting IP).</li><li>Cómo instalar los servicios invisibles (DHCP, DNS, servidores Web) que mantienen el mundo corporativo vivo.</li><li>Cómo atrincherar y fortificar esos servicios contra ejércitos de bots mediante Firewalls restrictivos y Criptografía VPN.</li></ol><p>Con esto concluye tu especialización de arquitectura local.</p><hr><h2 id="📘-anexo-diccionario-tecnico-formal" tabindex="-1">📘 ANEXO: Diccionario Técnico Formal <a class="header-anchor" href="#📘-anexo-diccionario-tecnico-formal" aria-label="Permalink to &quot;📘 ANEXO: Diccionario Técnico Formal&quot;">​</a></h2><ul><li><strong>Firewall (Cortafuegos):</strong> Dispositivo de hardware o aplicativo de software de red diseñado para monitorear, filtrar y dictaminar el tráfico entrante y saliente basándose en políticas de seguridad lógicas (ACLs) preestablecidas.</li><li><strong>ACL (Access Control List):</strong> Estructura de datos secuencial que contiene normativas de filtrado permisivo o restrictivo (Reglas) evaluadas cronológicamente para determinar el ruteo o descarte de paquetes IP y puertos de capa 4.</li><li><strong>Denegación Implícita (Default Deny):</strong> Paradigma de máxima seguridad cibernética en configuración de Firewalls donde toda interacción no explícita o positivamente autorizada en la lista de control, es mandatoriamente denegada y descartada por defecto.</li><li><strong>VPN (Virtual Private Network):</strong> Arquitectura de red lógica superpuesta que emplea mecanismos de encapsulamiento asimétrico (Túneles) y criptografía (IPsec/SSL) para extender de forma encriptada y remota una red local sobre una infraestructura de red pública o insegura (Internet).</li><li><strong>IPsec (Internet Protocol Security):</strong> Suite de protocolos IETF, fundamental en la creación de túneles VPN, que opera a nivel de Capa de Red (Capa 3) para proporcionar autenticación robusta, integridad matemática y confidencialidad en los paquetes IP.</li><li><strong>Fuerza Bruta (Brute Force Attack):</strong> Vector de ataque cibernético heurístico caracterizado por el envío masivo, automatizado y repetitivo de permutaciones de credenciales (passwords) con el objetivo algorítmico de vulnerar sistemas de autenticación débiles.</li></ul>',34)])])}const g=a(t,[["render",n]]);export{m as __pageData,g as default};
